// =====================================================================
// SOC-Lite · Ventana del reporte semanal y URLs de la API
// =====================================================================
const cfg = $('C · Set parámetros de reporte').first().json;
const days = Number(cfg.REPORT_PERIOD_DAYS || 7);
const base = String($env.BACKEND_BASE_URL || cfg.BACKEND_BASE_URL || 'http://backend:8000/api/v1').replace(/\/+$/, '');

const to = new Date();
const from = new Date(to.getTime() - days * 86400000);
const iso = (d) => d.toISOString().replace(/\.\d{3}Z$/, 'Z');

const body = {
  from: iso(from),
  to: iso(to),
  format: String($env.REPORT_FORMAT || cfg.REPORT_FORMAT || 'pdf'),
  report_type: String($env.REPORT_TYPE || cfg.REPORT_TYPE || 'operational'),
  period_days: days
};

return [
  {
    json: {
      report_type: body.report_type,
      format: body.format,
      period_from: body.from,
      period_to: body.to,
      period_days: days,
      api_url: base + '/reports/' + body.report_type + '?format=' + body.format + '&from=' + encodeURIComponent(body.from) + '&to=' + encodeURIComponent(body.to),
      inventory_url: base + '/reports/inventory?report_type=' + body.report_type + '&page=1&page_size=5',
      auth_url: base + '/auth/login',
      storage_dir: String($env.REPORT_STORAGE_DIR || cfg.REPORT_STORAGE_DIR || '/data/reports/soc-lite'),
      public_base_url: String($env.REPORT_PUBLIC_BASE_URL || cfg.REPORT_PUBLIC_BASE_URL || '').replace(/\/+$/, ''),
      recipients: String($env.REPORT_RECIPIENTS || cfg.REPORT_RECIPIENTS || ''),
      slack_channel: String($env.REPORT_SLACK_CHANNEL || cfg.REPORT_SLACK_CHANNEL || '#soc-reportes'),
      requested_by: 'system/n8n'
    }
  }
];

// =====================================================================
// SOC-Lite · Checksum SHA-256 y nombre del artefacto del reporte
// =====================================================================
const crypto = require('crypto');
const cfg = $('2 · Preparar ventana y URLs (Code)').first().json;
const login = $('3 · HTTP login backend (JWT)').first().json || {};
const item = $input.first();
const bin = item.binary && (item.binary.data || item.binary.report || Object.values(item.binary)[0]);

const buffer = bin && bin.data ? Buffer.from(bin.data, 'base64') : Buffer.alloc(0);
const sha256 = crypto.createHash('sha256').update(buffer).digest('hex');
const ext = cfg.format === 'xlsx' ? 'xlsx' : cfg.format === 'docx' ? 'docx' : 'pdf';
const stamp = String(cfg.period_from).slice(0, 10).replace(/-/g, '') + '-' + String(cfg.period_to).slice(0, 10).replace(/-/g, '');
const fileName = 'SOC-Lite_' + cfg.report_type + '_' + stamp + '.' + ext;
const relative = '/' + String(cfg.period_to).slice(0, 4) + '/' + String(cfg.period_to).slice(0, 7) + '/' + fileName;

return [
  {
    json: {
      report_type: cfg.report_type,
      format: cfg.format,
      period_from: cfg.period_from,
      period_to: cfg.period_to,
      period_days: cfg.period_days,
      file_name: fileName,
      file_path: String(cfg.storage_dir).replace(/\/+$/, '') + relative,
      storage_dir: cfg.storage_dir,
      public_url: cfg.public_base_url ? cfg.public_base_url + relative : '',
      file_size: buffer.length,
      checksum_sha256: sha256,
      mime_type: bin && bin.mimeType ? bin.mimeType : 'application/pdf',
      generated_at: new Date().toISOString(),
      api_url: cfg.api_url,
      inventory_url: cfg.inventory_url,
      recipients: cfg.recipients,
      slack_channel: cfg.slack_channel,
      access_token: login.access_token || null,
      title: 'SOC-Lite · Reporte operativo ' + String(cfg.period_from).slice(0, 10) + ' → ' + String(cfg.period_to).slice(0, 10),
      requested_by: cfg.requested_by
    },
    binary: item.binary
  }
];

// =====================================================================
// SOC-Lite · Cuerpo del correo y del aviso de Slack con el reporte
// =====================================================================
const r = $('5 · Checksum SHA-256 (Code)').first().json;
const reg = $('7 · Registrar reporte (PostgreSQL)').first().json || {};
const audit = $('8 · Bitácora EXPORT (PostgreSQL)').first().json || {};
const recipients = String(r.recipients || '')
  .split(',')
  .map((s) => s.trim())
  .filter((s) => s.length > 3 && s.indexOf('@') > 0);
const sizeMb = (Number(r.file_size || 0) / 1048576).toFixed(2);

const html = [
  '<h2>' + r.title + '</h2>',
  '<p>Reporte operativo del SOC generado automáticamente por n8n (workflow 05).</p>',
  '<ul>',
  '<li><b>Periodo:</b> ' + r.period_from + ' → ' + r.period_to + ' (' + r.period_days + ' días)</li>',
  '<li><b>Formato:</b> ' + r.format + ' · <b>Tamaño:</b> ' + sizeMb + ' MB</li>',
  '<li><b>Archivo:</b> ' + r.file_path + '</li>',
  '<li><b>SHA-256:</b> <code>' + r.checksum_sha256 + '</code></li>',
  '<li><b>ID en soclite.generated_reports:</b> ' + (reg.report_id || 'n/d') + '</li>',
  '</ul>',
  '<p>Descarga: <a href="' + (r.public_url || r.api_url) + '">' + (r.public_url || r.api_url) + '</a></p>',
  '<p>Evidencia de auditoría: entrada <b>#' + (audit.audit_id || 'n/d') + '</b> en <code>soclite.audit_log</code> (module=reports, action=EXPORT).</p>',
  '<p><small>SOC-Lite · generado el ' + r.generated_at + '</small></p>'
].join('\n');

const slackText = [
  ':page_with_curl: *Reporte operativo SOC-Lite ' + String(r.period_from).slice(0, 10) + ' → ' + String(r.period_to).slice(0, 10) + '*',
  'Formato: *' + r.format + '*  |  Tamaño: *' + sizeMb + ' MB*  |  Registro: *# ' + (reg.report_id || 'n/d') + '*',
  '*' + r.file_path + '*',
  'SHA-256: `' + r.checksum_sha256 + '`',
  r.public_url ? '<' + r.public_url + '|Descargar reporte>' : 'Disponible en el backend: <' + r.api_url + '|API de reportes>'
].join('\n');

return [
  {
    json: Object.assign({}, r, {
      recipients: recipients,
      email_to: recipients.join(', '),
      email_subject: r.title,
      email_html: html,
      slack_channel: r.slack_channel,
      slack_text: slackText,
      report_id: reg.report_id || null,
      audit_id: audit.audit_id || null,
      file_size_mb: Number(sizeMb)
    }),
    binary: $input.first().binary
  }
];
